    /**
     * @ignore
     * @method
     * @name sxbet#parseSxbetMarket
     * @description converts a single raw sx.bet market into one ccxt market whose two sides become the outcomes
     * @param {object} raw the raw sx.bet market object
     * @returns {object} a [market structure](https://docs.ccxt.com/#/?id=market-structure)
     */
    public virtual object parseSxbetMarket(object raw)
    {
        //
        //     {
        //         "status": "ACTIVE",
        //         "marketHash": "0x7154aa3580267e276cccd0f4f826464a05e3efd8e1c81d7717bef6b5ae88b07d",
        //         "outcomeOneName": "Los Angeles Rams",
        //         "outcomeTwoName": "San Francisco 49ers",
        //         "outcomeVoidName": "NO_CONTEST",
        //         "teamOneName": "Los Angeles Rams",
        //         "teamTwoName": "San Francisco 49ers",
        //         "type": 226,
        //         "gameTime": 1789086900,
        //         "line": -2.5, // present on spread/total markets only
        //         "sportXeventId": "L18870109",
        //         "liveEnabled": true,
        //         "sportLabel": "Football",
        //         "sportId": 8,
        //         "leagueId": 243,
        //         "leagueLabel": "NFL",
        //         "mainLine": true,
        //         "isQuarterLineMarket": false
        //     }
        //
        string marketHash = this.safeString(raw, "marketHash", "");
        object teamOneName = this.safeString(raw, "teamOneName");
        string? teamTwoName = this.safeString(raw, "teamTwoName");
        string? outcomeOneName = this.safeString(raw, "outcomeOneName");
        string? outcomeTwoName = this.safeString(raw, "outcomeTwoName");
        string eventSlug = this.shortenSlug(add(add(teamOneName, " "), teamTwoName));
        // one fixture carries many markets (moneyline, several spread/total lines, quarter/half
        // variants) whose outcomeOneName text can coincide or nearly coincide, so a text-only
        // slug isn't guaranteed unique. suffix with the market hash instead (always unique,
        // letters+digits only so it survives shortenSlug in one atomic word)
        // parseToInt-wrapped .length: the bare `const n = str.length;` statement is the php
        // transpiler's ARRAY hint (count()), which breaks on a string — this form emits
        // strlen()/len() correctly in both python and php
        Int64? hashLength = this.parseToInt(marketHash.Length);
        string? hashSuffix = slice(marketHash, subtract(hashLength, 6), null);
        string marketSlug = ((this.shortenSlug(outcomeOneName) + "_") + hashSuffix);
        string? marketSymbol = this.slugToMarketSymbol(eventSlug, marketSlug);
        string? status = this.safeStringUpper(raw, "status");
        bool active = (status == "ACTIVE");
        // guard against a zero sentinel for "no scheduled game time" - safeTimestamp would
        // turn it into the 1970 epoch
        Int64? gameTime = null;
        if ((this.safeInteger(raw, "gameTime", 0) != 0))
        {
            gameTime = this.safeTimestamp(raw, "gameTime");
        }
        List<object> outcomeLabels = new List<object>() {outcomeOneName, outcomeTwoName};
        List<object> outcomeIds = new List<object>() {marketHash, (marketHash + "-2")};
        List<object> outcomes = new List<object>() {};
        for (int oi = 0; oi < (outcomeLabels?.Count ?? 0); oi++)
        {
            string? label = ((string)outcomeLabels[oi]);
            string? outcomeHandle = this.slugToOutcomeSymbol(eventSlug, marketSlug, label);
            outcomes.Add(new Dictionary<string, object>() {
                { "id", getValue(outcomeIds, oi) },
                { "outcomeId", getValue(outcomeIds, oi) },
                { "outcome", outcomeHandle },
                { "market", marketSymbol },
                { "label", label },
                { "active", active },
                { "winner", null },
                { "settleFraction", null },
                { "info", raw },
            });
        }
        return new Dictionary<string, object>() {
            { "id", marketHash },
            { "market", marketSymbol },
            { "base", "USDC" },
            { "quote", "USDC" },
            { "settle", null },
            { "baseId", marketHash },
            { "quoteId", "USDC" },
            { "settleId", null },
            { "type", "prediction" },
            { "marketType", "binary" },
            { "executionModel", "clob" },
            { "spot", false },
            { "margin", false },
            { "swap", false },
            { "future", false },
            { "option", false },
            { "prediction", true },
            { "active", active },
            { "resolved", false },
            { "resolvedOutcome", null },
            { "contract", false },
            { "linear", null },
            { "inverse", null },
            { "contractSize", null },
            { "expiry", gameTime },
            { "expiryDatetime", this.iso8601(gameTime) },
            { "strike", null },
            { "optionType", null },
            { "taker", 0 },
            { "maker", 0 },
            { "percentage", true },
            { "tierBased", false },
            { "feeSide", "get" },
            { "precision", new Dictionary<string, object>() {
                { "amount", 0.000001 },
                { "price", 0.00125 },
            } },
            { "limits", new Dictionary<string, object>() {
                { "leverage", new Dictionary<string, object>() {
                    { "min", 1 },
                    { "max", 1 },
                } },
                { "amount", new Dictionary<string, object>() {
                    { "min", 1 },
                    { "max", null },
                } },
                { "price", new Dictionary<string, object>() {
                    { "min", 0 },
                    { "max", 1 },
                } },
                { "cost", new Dictionary<string, object>() {
                    { "min", 1 },
                    { "max", null },
                } },
            } },
            { "outcomes", outcomes },
            { "info", raw },
            { "created", null },
        };
    }

    /**
     * @method
     * @name sxbet#fetchEvents
     * @description fetches sx.bet fixtures (one fixture = one event, its markets are every moneyline/spread/total line on that fixture) scoped by eventId, leagueId, sportId or a free-text query/tags match against team and league names — always live from the API, never the local cache (it POPULATES the cache for later event()/outcome lookups). query/queries/tags are matched client-side over a bounded scan of /markets/active — the venue's GET /search covers team names only (not league or sport labels) and is not wired here yet
     * @see https://docs.sx.bet/api-reference/get-markets-active
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {string} [params.eventId] direct lookup by unified event id (the sx.bet sportXeventId, e.g. 'L18870109')
     * @param {string} [params.query] free-text search matched against team and league names
     * @param {string[]} [params.queries] multiple free-text searches (alternative to query, unioned)
     * @param {string[]} [params.tags] matched identically to query/queries (sx.bet has no tag taxonomy)
     * @param {int} [params.leagueId] sx.bet league id (e.g. 243 for NFL) — fetched server-side
     * @param {int} [params.sportId] sx.bet sport id (e.g. 8 for Football) — fetched server-side
     * @param {string} [params.status] 'active' | 'inactive' | 'closed' | 'all'
     * @param {int} [params.limit] max number of events to return
     * @returns {object[]} an array of event structures
     */
    public async override Task<List<ccxt.PredictionEvent>> FetchEvents(object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        this.requireEventQuery(parameters);
        string? eventId = this.safeString2(parameters, "eventId", "slug");
        string? leagueId = this.safeString(parameters, "leagueId");
        string? sportId = this.safeString(parameters, "sportId");
        List<object> queries = this.parseSearchQueries(parameters);
        List<object> tags = this.safeList(parameters, "tags", new List<object>() {});
        int tagsLength = tags.Count;
        for (int i = 0; i < tagsLength; i++)
        {
            queries.Add(getValue(tags, i));
        }
        object rest = this.omit(parameters, new List<object>() {"eventId", "slug", "leagueId", "sportId", "query", "queries", "tags", "status", "sort", "searchIn", "limit"});
        object rawMarkets = null;
        if ((eventId != null))
        {
            rawMarkets = await this.fetchRawMarketsPaged(this.extend(new Dictionary<string, object>() {
                { "sportXeventId", eventId },
            }, rest), null);
            // the venue's sportXeventId filter on /markets/active is unreliable (observed live
            // returning every fixture) — enforce the scope client-side
            rawMarkets = this.filterRawMarketsByFixture(rawMarkets, eventId);
        } else if ((leagueId != null))
        {
            rawMarkets = await this.fetchRawMarketsPaged(this.extend(new Dictionary<string, object>() {
                { "leagueId", leagueId },
            }, rest), null);
        } else if ((sportId != null))
        {
            rawMarkets = await this.fetchRawMarketsPaged(this.extend(new Dictionary<string, object>() {
                { "sportId", sportId },
            }, rest), null);
        } else
        {
            // no server-side scope left, only query/tags — full scan honoring the fetchMarkets
            // bound, then filter client-side (the venue's /search covers team names only)
            rawMarkets = await this.fetchRawMarketsPaged(rest, null);
        }
        int queriesLength = (queries?.Count ?? 0);
        if (queriesLength > 0)
        {
            List<object> filtered = new List<object>() {};
            int preFilterLength = getArrayLength(rawMarkets);
            for (int i = 0; i < preFilterLength; i++)
            {
                if (this.matchesEventQuery(getValue(rawMarkets, i), queries))
                {
                    filtered.Add(getValue(rawMarkets, i));
                }
            }
            rawMarkets = filtered;
        }
        Dictionary<string, object> grouped = new Dictionary<string, object>() {};
        List<object> order = new List<object>() {};
        int rawMarketsLength = getArrayLength(rawMarkets);
        for (int i = 0; i < rawMarketsLength; i++)
        {
            object raw = getValue(rawMarkets, i);
            string? sportXeventId = this.safeString(raw, "sportXeventId");
            if ((sportXeventId == null))
            {
                continue;
            }
            if (!(((sportXeventId != null) && grouped.ContainsKey(sportXeventId))))
            {
                grouped[(string)sportXeventId] = new List<object>() {};
                order.Add(sportXeventId);
            }
            ((IList<object>)getValue(grouped, sportXeventId)).Add(raw);
        }
        if ((this.markets == null))
        {
            this.markets = this.createSafeDictionary();
        }
        List<object> result = new List<object>() {};
        int orderLength = (order?.Count ?? 0);
        for (int i = 0; i < orderLength; i++)
        {
            string? fixtureId = ((string)getValue(order, i));
            Dictionary<string, object> eventVar = this.parseEvent(fixtureId, getValue(grouped, fixtureId));
            List<object> evMarkets = this.safeList(eventVar, "markets", new List<object>() {});
            int evMarketsLength = evMarkets.Count;
            for (int j = 0; j < evMarketsLength; j++)
            {
                object m = getValue(evMarkets, j);
                ((IDictionary<string,object>)this.markets)[(string)getValue(m, "market")] = m;
            }
            result.Add(eventVar);
        }
        this.populateOutcomes();
        this.setEvents(result);
        object postParams = this.omit(parameters, new List<object>() {"leagueId", "sportId", "query", "queries", "tags"});
        return ccxt.BaseExchange.ToPredictionEventList(this.applyEventFetchParams(result, postParams, new List<object>() {}));
    }

