        {
            throw new ArgumentsRequired ((this.id + " approve() requires params.amount - the USDC amount to move into the proxy wallet")) ;
        }
        IDictionary<string, object> proxy = await this.fetchSxbetProxy();
        bool? deployed = this.safeBool(proxy, "deployed", false);
        if ((deployed != true))
        {
            await this.sxbetPrivatePostUserDeployProxy();
            // deployment is asynchronous - poll until the proxy exists
            for (int i = 0; i < 30; i++)
            {
                await this.sleep(2000);
                IDictionary<string, object> state = await this.fetchSxbetProxy();
                if ((this.safeBool(state, "deployed", false) == true))
                {
                    break;
                }
            }
        }
        IDictionary<string, object> obv3 = await this.loadSxObv3Metadata();
        IDictionary<string, object> activeAsset = this.safeDict(obv3, "activeAsset", new Dictionary<string, object>() {});
        Int64? chainId = this.safeInteger(obv3, "chainId");
        string? usdcAddress = this.safeString(activeAsset, "baseToken");
        // the permit spender is the venue's transfer-to-proxy executor, published in /metadata/obv3
        string? executorAddress = this.safeString(obv3, "transferToProxyExecutorAddress");
        string? tokenAddress = this.safeString(parameters, "tokenAddress", usdcAddress);
        if ((tokenAddress == null))
        {
            throw new BadRequest ((this.id + " approve() could not resolve the base token address from /metadata/obv3")) ;
        }
        string? spender = null;
        IList<object> spenderparametersVariable = (IList<object>)this.handleOptionStringAndParams2(parameters, "approve", "spender", "transferToProxySpender", executorAddress);
        spender = (string)spenderparametersVariable[0];
        parameters = spenderparametersVariable[1];
        if ((spender == null))
        {
            throw new BadRequest ((this.id + " approve() could not resolve the transfer-to-proxy executor from /metadata/obv3 - pass params.spender")) ;
        }
        IDictionary<string, object> chains = this.safeDict(this.options, "chains", new Dictionary<string, object>() {});
        IDictionary<string, object> chainConfig = this.safeDict(chains, this.numberToString(chainId), new Dictionary<string, object>() {});
        string? rpcUrl = this.safeString(parameters, "rpcUrl", this.safeString(chainConfig, "rpcUrl"));
        if ((rpcUrl == null))
        {
            throw new ArgumentsRequired ((((this.id + " approve() has no RPC endpoint configured for chainId ") + this.numberToString(chainId)) + " - pass params.rpcUrl")) ;
        }
        string owner = this.walletAddress;
        string nonceCallData = ("0x7ecebe00" + this.padHexAddress(owner)); // nonces(address)
        object nonceResult = await this.ethRpc(rpcUrl, "eth_call", new List<object>() {new Dictionary<string, object>() {
    { "to", tokenAddress },
    { "data", nonceCallData },
}, "latest"});
        string? nonceHex = this.hexToRlpBytes(nonceResult);
        string? nonce = (nonceHex == "") ? "0" : this.numberToString(this.hexToInt(nonceHex));
        string? tokenName = await this.fetchErc20Name(rpcUrl, tokenAddress);
        Int64? defaultDeadlineSeconds = this.safeInteger(this.options, "approveDeadlineSeconds", 7200);
        Int64? deadline = this.safeInteger(parameters, "deadline", this.sum(this.seconds(), defaultDeadlineSeconds));
        string value = this.decimalToPrecision(Precise.stringMul(this.numberToString(amount), "1000000"), ROUND, 0, DECIMAL_PLACES);
        Dictionary<string, object> domain = new Dictionary<string, object>() {
            { "name", tokenName },
            { "version", "1" },
            { "chainId", chainId },
            { "verifyingContract", tokenAddress },
        };
        Dictionary<string, object> messageTypes = new Dictionary<string, object>() {
            { "Permit", new List<object>() {new Dictionary<string, object>() {
    { "name", "owner" },
    { "type", "address" },
}, new Dictionary<string, object>() {
    { "name", "spender" },
    { "type", "address" },
}, new Dictionary<string, object>() {
    { "name", "value" },
    { "type", "uint256" },
}, new Dictionary<string, object>() {
    { "name", "nonce" },
    { "type", "uint256" },
}, new Dictionary<string, object>() {
    { "name", "deadline" },
    { "type", "uint256" },
}} },
        };
        Dictionary<string, object> messageData = new Dictionary<string, object>() {
            { "owner", owner },
            { "spender", spender },
            { "value", value },
            { "nonce", nonce },
            { "deadline", deadline },
        };
        byte[] encoded = this.ethEncodeStructuredData(domain, messageTypes, messageData);
        string? digest = ((string)this.hashEip712Digest(encoded));
        string? signature = ((string)this.signDigest(digest, this.privateKey));
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "owner", owner },
            { "spender", spender },
            { "tokenAddress", tokenAddress },
            { "value", value },
            { "deadline", this.numberToString(deadline) },
            { "signature", signature },
        };
        object rest = this.omit(parameters, new List<object>() {"amount", "tokenAddress", "deadline", "rpcUrl"});
        Dictionary<string, object> response = await this.sxbetPrivatePostUserTransferToProxy(this.extend(request, rest));
        IDictionary<string, object> data = this.safeDict(response, "data", new Dictionary<string, object>() {});
        return new Dictionary<string, object>() {
            { "info", response },
            { "id", this.safeString(data, "sessionId") },
        };
    }

    /**
     * @method
     * @name sxbet#createOrder
     * @description places an order on sx.bet's v3 unified orderbook - a 'limit' order rests with GTC time-in-force, a 'market' order fills immediately with IOC (or FOK via params.timeInForce). sx.bet has no shares - 'amount' is the USDC stake to risk, and 'price' is the implied probability (0-1) of the requested outcome. 'sell' bets the OPPOSITE outcome of the one requested (sx.bet is bilateral: there is no owned position to sell, only the complementary side of the same market)
     * @see https://docs.sx.bet/api-reference/post-orders-v3
     * @param {string} outcome unified outcome or outcome token id
     * @param {string} type 'limit' (GTC resting order) or 'market' (IOC immediate fill)
     * @param {string} side 'buy' backs the requested outcome, 'sell' backs the complementary one
     * @param {float} amount the USDC amount to stake/risk
     * @param {float} [price] implied probability (0-1) of the requested outcome; required for both order types
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {string} [params.timeInForce] overrides the derived value - 'GTC', 'IOC' or 'FOK'
     * @param {int} [params.expiry] unix seconds the order expires at; must be in the future (zero and past values are rejected, so is anything inside the fixture's betting-delay window - /metadata/obv3 resolves the delay per sport/league, live vs pregame), defaults to options.defaultOrderExpirySeconds from now
     * @param {string} [params.salt] overrides the random salt differentiating this order
     * @param {string} [params.clientOrderId] caller-chosen id echoed back on reads (max 64 chars)
     * @param {boolean} [params.waitForOutcome] wait for the matching outcome inline (default true)
     * @param {boolean} [params.useBetCredits] fund the stake from bet credits instead of the proxy balance (IOC/FOK only)
     * @param {string} [params.externalUserId] partner attribution id echoed back on order, fill and trade reads
     * @returns {object} a [prediction order structure](https://docs.ccxt.com/#/?id=prediction-order-structure)
     */
    public async override Task<ccxt.PredictionOrder> CreateOrder(string outcome, string type, string side, double amount, double? price = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        this.checkRequiredCredentials();
        await this.loadOutcome(outcome);
        IDictionary<string, object> outcomeObj = this.outcome(outcome);
        if (((type != "limit")) && ((type != "market")))
        {
            throw new InvalidOrder (((this.id + " createOrder() type must be 'limit' or 'market', got ") + type)) ;
        }
        if ((price == null))
        {
            throw new ArgumentsRequired ((this.id + " createOrder() requires a price - the implied probability of the requested outcome")) ;
        }
        // the venue has no post-only or trigger mechanics - reject the unified params instead
        // of forwarding fields the exchange would silently ignore
        bool? postOnly = this.safeBool(parameters, "postOnly", false);
        if ((postOnly == true))
        {
            throw new NotSupported ((this.id + " createOrder() does not support postOnly - GTC orders may cross on entry")) ;
        }
        string? triggerPrice = this.safeStringN(parameters, new List<object>() {"triggerPrice", "stopLossPrice", "takeProfitPrice"});
        if ((triggerPrice != null))
        {
            throw new NotSupported ((this.id + " createOrder() does not support trigger, stop-loss or take-profit orders")) ;
        }
        string? marketHash = this.safeString((outcomeObj != null && ((IDictionary<string, object>)outcomeObj).ContainsKey("info") ? ((IDictionary<string, object>)outcomeObj)["info"] : null), "marketHash", "");
        string? outcomeId = this.safeString(outcomeObj, "outcomeId");
        bool isOutcomeOne = ((outcomeId == marketHash));
        bool isBuy = ((side == "buy"));
        // 'sell' bets the complementary outcome, mirroring the requested outcome's own probability -
        // matches the normalize-to-one-book convention used by other prediction venues
        bool isMakerBettingOutcomeOne = isBuy ? isOutcomeOne : !isOutcomeOne;
        string? priceStr = this.numberToString(price);
        string? probability = isBuy ? priceStr : Precise.stringSub("1", priceStr);
        IDictionary<string, object> obv3 = await this.loadSxObv3Metadata();
        IDictionary<string, object> domain = this.safeDict(obv3, "domain", new Dictionary<string, object>() {});
        IDictionary<string, object> activeAsset = this.safeDict(obv3, "activeAsset", new Dictionary<string, object>() {});
        string? baseToken = this.safeString(activeAsset, "baseToken");
        string? oddsLadderStepSize = this.numberToString(this.safeInteger(obv3, "oddsLadderStepSize", 125));
        string? roundedProbability = ((string)this.roundOddsToLadder(probability, oddsLadderStepSize));
        string percentageOdds = this.decimalToPrecision(Precise.stringMul(roundedProbability, "100000000000000000000"), ROUND, 0, DECIMAL_PLACES);
        string? amountStr = this.numberToString(amount);
        string totalBetSize = this.decimalToPrecision(Precise.stringMul(amountStr, "1000000"), ROUND, 0, DECIMAL_PLACES);
        string? saltNumber = this.safeString(parameters, "salt", this.numberToString(this.milliseconds()));
        // the request body carries the salt in 32-byte-hex form; the signed struct carries the
        // same value in uint256 form - both parse to one number server-side. assign to bare locals
        // before padStart - see the transpiler notes
        string saltHexRaw = this.intToBase16(this.parseToInt(saltNumber));
        string saltHexPadded = (saltHexRaw as String).PadLeft(Convert.ToInt32(64), Convert.ToChar("0"));
        string saltHex = ("0x" + saltHexPadded);
        Int64? defaultExpirySeconds = this.safeInteger(this.options, "defaultOrderExpirySeconds", 86400);
        Int64? expiry = this.safeInteger(parameters, "expiry", this.sum(this.seconds(), defaultExpirySeconds));
        string defaultTif = "IOC";
        if ((type == "limit"))
        {
            defaultTif = "GTC";
        }
        string? timeInForce = null;
        IList<object> timeInForceparametersVariable = (IList<object>)this.handleOptionStringAndParams(parameters, "createOrder", "timeInForce", defaultTif);
        timeInForce = (string)timeInForceparametersVariable[0];
        parameters = timeInForceparametersVariable[1];
        // an explicit IOC/FOK on a 'limit' order is honored verbatim - the venue executes exactly
        // that time-in-force. only GTC on a 'market' order is refused: it would silently rest,
        // contradicting the immediate-fill semantics the type promises
        if (((type == "market")) && (timeInForce == "GTC"))
        {
            throw new InvalidOrder ((this.id + " createOrder() market orders cannot be GTC - use type 'limit' for a resting order")) ;
        }
        string maker = this.walletAddress;
        Dictionary<string, object> messageTypes = new Dictionary<string, object>() {
            { "Order", new List<object>() {new Dictionary<string, object>() {
    { "name", "marketHash" },
    { "type", "bytes32" },
}, new Dictionary<string, object>() {
    { "name", "baseToken" },
    { "type", "address" },
}, new Dictionary<string, object>() {
    { "name", "totalBetSize" },
    { "type", "uint256" },
}, new Dictionary<string, object>() {
    { "name", "percentageOdds" },
    { "type", "uint256" },
}, new Dictionary<string, object>() {
    { "name", "salt" },
    { "type", "uint256" },
}, new Dictionary<string, object>() {
    { "name", "expiry" },
    { "type", "uint256" },
}, new Dictionary<string, object>() {
    { "name", "maker" },
    { "type", "address" },
}, new Dictionary<string, object>() {
    { "name", "isMakerBettingOutcomeOne" },
    { "type", "bool" },
}} },
        };
        Dictionary<string, object> messageData = new Dictionary<string, object>() {
            { "marketHash", marketHash },
            { "baseToken", baseToken },
            { "totalBetSize", totalBetSize },
            { "percentageOdds", percentageOdds },
            { "salt", saltNumber },
            { "expiry", expiry },
            { "maker", maker },
            { "isMakerBettingOutcomeOne", isMakerBettingOutcomeOne },
        };
        byte[] encoded = this.ethEncodeStructuredData(domain, messageTypes, messageData);
        string? digest = ((string)this.hashEip712Digest(encoded));
        string? orderSignature = ((string)this.signDigest(digest, this.privateKey));
        Dictionary<string, object> orderItem = new Dictionary<string, object>() {
            { "marketHash", marketHash },
            { "maker", maker },
            { "totalBetSize", totalBetSize },
            { "percentageOdds", percentageOdds },
            { "salt", saltHex },
            { "expiry", expiry },
            { "baseToken", baseToken },
            { "isMakerBettingOutcomeOne", isMakerBettingOutcomeOne },
            { "timeInForce", timeInForce },
            { "orderSignature", orderSignature },
        };
        string? clientOrderId = this.safeString(parameters, "clientOrderId");
        if ((clientOrderId != null))
        {
            orderItem["clientOrderId"] = clientOrderId;
        }
        // useBetCredits and externalUserId are per-order fields - route them into the order item,
        // not the top-level body, where the venue would silently ignore them
        bool? useBetCredits = this.safeBool(parameters, "useBetCredits");
        if ((useBetCredits != null))
        {
            orderItem["useBetCredits"] = useBetCredits;
        }
        string? externalUserId = this.safeString(parameters, "externalUserId");
        if ((externalUserId != null))
        {
            orderItem["externalUserId"] = externalUserId;
        }
        bool? waitForOutcome = this.safeBool(parameters, "waitForOutcome", true);
        object rest = this.omit(parameters, new List<object>() {"salt", "expiry", "clientOrderId", "waitForOutcome", "useBetCredits", "externalUserId"});
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "orders", new List<object>() {orderItem} },
            { "waitForOutcome", waitForOutcome },
        };
        Dictionary<string, object> response = await this.sxbetPrivatePostOrdersV3(this.extend(request, rest));
        IDictionary<string, object> data = this.safeDict(response, "data", new Dictionary<string, object>() {});
        List<object> results = this.safeList(data, "orders", new List<object>() {});
        IDictionary<string, object> first = this.safeDict(results, 0, new Dictionary<string, object>() {});
        string? status = this.safeStringUpper(first, "status");
        if (status == "FAILED")
        {
            string? reason = this.safeString(first, "reason", "FAILED");
            string feedback = ((this.id + " createOrder() rejected: ") + reason);
            this.throwExactlyMatchedException((this.exceptions != null && ((IDictionary<string, object>)this.exceptions).ContainsKey("exact") ? ((IDictionary<string, object>)this.exceptions)["exact"] : null), reason, feedback);
            throw new InvalidOrder (feedback) ;
        }
        // with waitForOutcome the venue reports the matching result inline:
        //     "outcome": { "state": "FULLY_FILLED", "fillAmount": "2000000", "remainingAmount": "0", "matchIds": [...] }
        // documented states: RESTED, FULLY_FILLED, PARTIAL_FILL_DONE, PARTIAL_FILL_RESTED, TIMEOUT and
        // CANCELLED with cancelReason NO_LIQUIDITY, INTERNAL_ERROR, ENGINE_SHUTDOWN, EXPIRED or INSUFFICIENT_BALANCE
        IDictionary<string, object> matchOutcome = this.safeDict(first, "outcome");
        string usdcDecimals = "1000000";
        double? filled = null;
        double? remaining = null;
        string? orderStatus = null;
        if ((matchOutcome != null))
        {
            string? fillAmountRaw = this.safeString(matchOutcome, "fillAmount");
            string? remainingRaw = this.safeString(matchOutcome, "remainingAmount");
            if ((fillAmountRaw != null))
            {
                filled = this.parseNumber(Precise.stringDiv(fillAmountRaw, usdcDecimals, 6));
            }
            if ((remainingRaw != null))
            {
                remaining = this.parseNumber(Precise.stringDiv(remainingRaw, usdcDecimals, 6));
            }
            string? state = this.safeStringUpper(matchOutcome, "state");
            if ((state == "RESTED") || (state == "PARTIAL_FILL_RESTED"))
            {
                orderStatus = "open";
            } else if (state == "FULLY_FILLED")
            {
                orderStatus = "closed";
            } else if (state == "PARTIAL_FILL_DONE")
            {
                // the unmatched remainder of an IOC was cancelled by the venue
                orderStatus = "canceled";
            } else if (state == "CANCELLED")
            {
                // the documented field is cancelReason; 'reason' is kept for older responses
                string? reason = this.safeStringUpper2(matchOutcome, "cancelReason", "reason");
                orderStatus = ((reason == "EXPIRED")) ? "expired" : "canceled";
            }
        }
        Int64 now = this.milliseconds();
        return ccxt.BaseExchange.ToPredictionOrder(this.safePredictionOrder(new Dictionary<string, object>() {             { "id", this.safeString2(first, "orderId", "orderHash") },             { "clientOrderId", this.safeString(first, "clientOrderId", clientOrderId) },             { "info", response },             { "timestamp", now },             { "datetime", this.iso8601(now) },             { "status", orderStatus },             { "filled", filled },             { "remaining", remaining },             { "cost", filled },             { "outcome", this.safeString(outcomeObj, "outcome") },             { "outcomeId", outcomeId },             { "label", this.safeString(outcomeObj, "label") },             { "market", this.safeString(outcomeObj, "market") },             { "type", type },             { "timeInForce", timeInForce },             { "side", side },             { "price", this.parseNumber(roundedProbability) },             { "amount", amount },             { "fee", null },             { "trades", new List<object>() {} },         }, ((object)outcomeObj)));
    }

    /**
     * @ignore
     * @method
     * @name sxbet#parseSxbetCancelResponse
     * @description parses the shared v3 cancel response ({cancelled, notCancelled, unconfirmed}) into order structures
     * @param {object} response the raw DELETE /orders-v3 response
     * @returns {object[]} a list of [prediction order structures](https://docs.ccxt.com/#/?id=prediction-order-structure)
     */
    public virtual object parseSxbetCancelResponse(object response)
    {
        IDictionary<string, object> data = this.safeDict(response, "data", new Dictionary<string, object>() {});
        List<object> result = new List<object>() {};
        // by-id cancels report 'cancelled'; the /all and /event paths submit asynchronously and
        // report 'cancelledSubmitted' instead - treat both like cancelled
        List<object> cancelled = this.safeList2(data, "cancelled", "cancelledSubmitted", new List<object>() {});
        int cancelledLength = cancelled.Count;
        for (int i = 0; i < cancelledLength; i++)
        {
            result.Add(this.safePredictionOrder(new Dictionary<string, object>() {
                { "id", this.safeString(getValue(cancelled, i), "orderId") },
                { "status", "canceled" },
                { "info", response },
            }));
        }
        List<object> notCancelled = this.safeList(data, "notCancelled", new List<object>() {});
        int notCancelledLength = notCancelled.Count;
        for (int i = 0; i < notCancelledLength; i++)
        {
            // the venue reports why (e.g. NOT_FOUND) - the order was not cancelled, report it honestly
            result.Add(this.safePredictionOrder(new Dictionary<string, object>() {
                { "id", this.safeString(getValue(notCancelled, i), "orderId") },
                { "status", null },
                { "info", response },
            }));
        }
        List<object> unconfirmed = this.safeList(data, "unconfirmed", new List<object>() {});
        int unconfirmedLength = unconfirmed.Count;
        for (int i = 0; i < unconfirmedLength; i++)
        {
            result.Add(this.safePredictionOrder(new Dictionary<string, object>() {
                { "id", this.safeString(getValue(unconfirmed, i), "orderId") },
                { "status", null },
                { "info", response },
            }));
        }
        return result;
    }

    /**
     * @method
     * @name sxbet#cancelOrder
     * @description cancels one resting maker order - v3 cancels are plain api-key-authenticated DELETE requests, no signature involved
     * @see https://docs.sx.bet/api-reference/delete-orders-v3
     * @param {string} id the order id
     * @param {string} [outcome] not used by sxbet.cancelOrder
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} a [prediction order structure](https://docs.ccxt.com/#/?id=prediction-order-structure)
     */
    public async override Task<ccxt.PredictionOrder> CancelOrder(string id, string outcome = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        this.checkRequiredCredentials();
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "orders", new List<object>() {new Dictionary<string, object>() {
    { "orderId", id },
}} },
        };
        Dictionary<string, object> response = await this.sxbetPrivateDeleteOrdersV3(this.extend(request, parameters));
        List<object> orders = ((List<object>)this.parseSxbetCancelResponse(response));
        return ccxt.BaseExchange.ToPredictionOrder(this.safeDict(orders, 0));
    }

    /**
     * @method
     * @name sxbet#cancelOrders
     * @description cancels multiple resting maker orders in one request - v3 cancels are plain api-key-authenticated DELETE requests, no signature involved
     * @see https://docs.sx.bet/api-reference/delete-orders-v3
     * @param {string[]} ids the order ids to cancel
     * @param {string} [outcome] not used by sxbet.cancelOrders
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object[]} a list of [prediction order structures](https://docs.ccxt.com/#/?id=prediction-order-structure)
     */
    public async override Task<List<ccxt.PredictionOrder>> CancelOrders(object ids, string outcome = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        this.checkRequiredCredentials();
        int idsLength = getArrayLength(ids);
        if ((idsLength == 0))
        {
            throw new ArgumentsRequired ((this.id + " cancelOrders() requires a non-empty ids argument")) ;
        }
        // the venue caps one cancel request at maxCancelOrders ids (100, see /metadata/obv3) -
        // chunk larger batches instead of letting the whole request 400
        Int64? chunkSize = this.safeInteger(this.options, "cancelOrdersBatchSize", 100);
        Int64? chunkCount = this.parseToInt(divide(this.sum(idsLength, subtract(chunkSize, 1)), chunkSize));
        List<object> result = new List<object>() {};
        for (int c = 0; isLessThan(c, chunkCount); c++)
        {
            Int64? start = (c * chunkSize);
            object end = add(start, chunkSize);
            if (isGreaterThan(end, idsLength))
            {
                end = idsLength;
            }
            List<object> orderItems = new List<object>() {};
            for (object i = start; isLessThan(i, end); postFixIncrement(ref i))
            {
                orderItems.Add(new Dictionary<string, object>() {
                    { "orderId", getValue(ids, i) },
                });
            }
            Dictionary<string, object> request = new Dictionary<string, object>() {
                { "orders", orderItems },
            };
            Dictionary<string, object> response = await this.sxbetPrivateDeleteOrdersV3(this.extend(request, parameters));
            result = this.arrayConcat(result, this.parseSxbetCancelResponse(response));
        }
        return ccxt.BaseExchange.ToPredictionOrderList(result);
    }

    /**
     * @method
     * @name sxbet#cancelAllOrders
     * @description cancels every resting maker order of the account, or every order of one fixture via params.eventId - v3 cancels are plain api-key-authenticated DELETE requests, no signature involved
     * @see https://docs.sx.bet/api-reference/delete-orders-v3-all
     * @see https://docs.sx.bet/api-reference/delete-orders-v3-event
     * @param {string} [outcome] not used by sxbet.cancelAllOrders
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {string} [params.eventId] cancels every order across every market of this fixture instead of the account-wide path (params.sportXeventId is accepted too)
     * @returns {object[]} a list of [prediction order structures](https://docs.ccxt.com/#/?id=prediction-order-structure)
     */
    public async virtual Task<List<ccxt.PredictionOrder>> CancelAllOrders(string outcome = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        this.checkRequiredCredentials();
        string? eventId = this.safeString2(parameters, "eventId", "sportXeventId");
        object rest = this.omit(parameters, new List<object>() {"eventId", "sportXeventId"});
        bool isEventScoped = ((eventId != null));
        Dictionary<string, object> response = null;
        if (isEventScoped)
        {
            // the event route takes eventId in the QUERY string, not the body - sign() urlencodes
            // body-less DELETE params
            Dictionary<string, object> request = new Dictionary<string, object>() {
                { "eventId", eventId },
            };
            response = await this.sxbetPrivateDeleteOrdersV3Event(this.extend(request, rest));
        } else
        {
            response = await this.sxbetPrivateDeleteOrdersV3All(rest);
        }
        List<object> result = ((List<object>)this.parseSxbetCancelResponse(response));
        // both paths paginate their async submission - keep going on the SAME route while more remain
        bool? hasMore = this.safeBool(this.safeDict(response, "data", new Dictionary<string, object>() {}), "hasMore", false);
        object guard = 0;
        while (((hasMore == true)) && (isLessThan(guard, 50)))
        {
            Dictionary<string, object> nextResponse = null;
            if (isEventScoped)
            {
                Dictionary<string, object> nextRequest = new Dictionary<string, object>() {
                    { "eventId", eventId },
                };
                nextResponse = await this.sxbetPrivateDeleteOrdersV3Event(this.extend(nextRequest, rest));
            } else
            {
                nextResponse = await this.sxbetPrivateDeleteOrdersV3All(rest);
            }
            result = this.arrayConcat(result, this.parseSxbetCancelResponse(nextResponse));
            hasMore = this.safeBool(this.safeDict(nextResponse, "data", new Dictionary<string, object>() {}), "hasMore", false);
            guard = this.sum(guard, 1);
        }
        return ccxt.BaseExchange.ToPredictionOrderList(result);
    }

    /**
     * @ignore
     * @method
     * @name sxbet#parsePredictionOrder
     * @description parses one raw GET /orders row into a unified prediction order. every sx.bet maker order is a 'buy' of the outcome it bets on (isMakerBettingOutcomeOne selects the side), priced at the maker's own implied probability
     * @param {object} order the raw sx.bet order object
     * @param {object} [market] the outcome object the order belongs to (resolved from the cache by outcomeId when omitted)
     * @returns {object} a [prediction order structure](https://docs.ccxt.com/#/?id=prediction-order-structure)
     */
    public override Dictionary<string, object> parsePredictionOrder(object order, object market = null)
    {
        //
        //     {
        //         "id": "0x112a4f19f20395aefcdb5d26f3f8aab0d96b1aff7ce346c0bfb13d9490340cdf",
        //         "marketHash": "0xbf06c6379c922d8118612d1d7493b20f6df6929437fbf6022904327f9516a2eb",
        //         "userAddress": "0xbcc6D643e4159A75ED1dB4e13330230B82F2AEe5",
        //         "wallet": "0x4361123dbdc1D812fdf7D27045aF358C9C8AA70A",
        //         "isBettingOutcomeOne": true,
        //         "percentageOdds": "40000000000000000000",
        //         "totalBetSize": "3000000",
        //         "remainingSize": "3000000",
        //         "expiry": null,
        //         "status": "ACTIVE",
        //         "inactiveReason": null,
        //         "eventId": "L12003787",
        //         "createdAt": "2026-07-31T18:45:42.636Z",
        //         "updatedAt": "2026-07-31T18:45:42.838Z"
        //     }
        //
        string? orderId = this.safeString2(order, "id", "orderId");
        string marketHash = this.safeString(order, "marketHash", "");
        bool? isBettingOutcomeOne = this.safeBool(order, "isBettingOutcomeOne", true);
        string? outcomeId = null;
        if ((isBettingOutcomeOne == true))
        {
            outcomeId = marketHash;
        } else
        {
            outcomeId = ((marketHash + "-2"));
        }
        IDictionary<string, object> outcomeObj = this.safeOutcome(outcomeId, ((object)market));
        string oneDenom = "100000000000000000000";
        string usdcDecimals = "1000000";
        string? percentageOdds = this.safeString(order, "percentageOdds");
        double? price = ((percentageOdds != null)) ? this.parseNumber(Precise.stringDiv(percentageOdds, oneDenom)) : null;
        string? totalBetSize = this.safeString(order, "totalBetSize", "0");
        string? remainingSize = this.safeString(order, "remainingSize", totalBetSize);
        string? filledRaw = Precise.stringSub(totalBetSize, remainingSize);
        double? amount = this.parseNumber(Precise.stringDiv(totalBetSize, usdcDecimals, 6));
        double? filled = this.parseNumber(Precise.stringDiv(filledRaw, usdcDecimals, 6));
        double? remaining = this.parseNumber(Precise.stringDiv(remainingSize, usdcDecimals, 6));
        string? orderStatus = this.safeStringUpper(order, "status");
        string? inactiveReason = this.safeStringUpper(order, "inactiveReason");
        string status = "open";
        if (orderStatus == "INACTIVE")
        {
            // documented inactiveReason enum: FILLED, USER_REQUESTED, EXPIRED, NO_LIQUIDITY,
            // INSUFFICIENT_BALANCE, EVENT_LIFECYCLE, MARKET_HALTED, HEARTBEAT_TIMEOUT, SYSTEM
            if (inactiveReason == "FILLED")
            {
                status = "closed";
            } else if (inactiveReason == "EXPIRED")
            {
                status = "expired";
            } else
            {
                status = "canceled";
            }
        }
        Int64? timestamp = this.parse8601(this.safeString(order, "createdAt"));
        return ((Dictionary<string, object>)((object)(this.safePredictionOrder(new Dictionary<string, object>() {
            { "id", orderId },
            { "clientOrderId", this.safeString(order, "clientOrderId") },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "lastTradeTimestamp", this.parse8601(this.safeString(order, "updatedAt")) },
            { "status", status },
            { "type", "limit" },
            { "timeInForce", null },
            { "side", "buy" },
            { "price", price },
            { "average", null },
            { "amount", amount },
            { "filled", filled },
            { "remaining", remaining },
            { "cost", null },
            { "fee", null },
            { "reduceOnly", null },
            { "postOnly", null },
            { "trades", new List<object>() {} },
            { "outcome", this.safeString(outcomeObj, "outcome") },
            { "outcomeId", this.safeString(outcomeObj, "outcomeId", outcomeId) },
            { "label", this.safeString(outcomeObj, "label") },
            { "market", this.safeString(outcomeObj, "market") },
            { "info", order },
        }, outcomeObj))));
    }

    /**
     * @ignore
     * @method
     * @name sxbet#clampSxbetPerPage
     * @description clamps a user limit to the venue's hard perPage ceiling - every v3 listing route rejects perPage above 100, and deeper history is reachable through the nextKey cursor instead
     * @param {int} limit the user-requested limit
     * @returns {int} the limit clamped to at most 100
     */
    public virtual object clampSxbetPerPage(object limit)
    {
        int maxPerPage = 100;
        if (isEqual(limit, null))
        {
            return null;
        }
        return (isGreaterThan(limit, maxPerPage)) ? maxPerPage : limit;
    }

    /**
     * @method
     * @name sxbet#fetchOpenOrders
