    /**
     * @ignore
     * @method
     * @name sxbet#parseSxbetV3PublicTrade
     * @description parses one recent_trades_v3 publication (public TradeV3 shape) into a unified trade
     * @param {object} trade the raw public trade row
     * @returns {object} a [prediction trade structure](https://docs.ccxt.com/#/?id=prediction-trade-structure)
     */
    public virtual object parseSxbetV3PublicTrade(object trade)
    {
        string marketHash = this.safeString(trade, "marketHash", "");
        bool? isBettingOutcomeOne = this.safeBool(trade, "isBettingOutcomeOne", true);
        string? outcomeId = null;
        if ((isBettingOutcomeOne == true))
        {
            outcomeId = marketHash;
        } else
        {
            outcomeId = ((marketHash + "-2"));
        }
        IDictionary<string, object> outcomeObj = this.safeOutcome(outcomeId);
        string oneDenom = "100000000000000000000";
        string usdcDecimals = "1000000";
        string? odds = this.safeString(trade, "weightedAverageOdds");
        double? price = ((odds != null)) ? this.parseNumber(Precise.stringDiv(odds, oneDenom)) : null;
        string? stake = this.safeString(trade, "totalStake", "0");
        double? amount = this.parseNumber(Precise.stringDiv(stake, usdcDecimals, 6));
        Int64? timestamp = this.parse8601(this.safeString(trade, "betTime"));
        return this.safePredictionTrade(new Dictionary<string, object>() {
            { "id", this.safeString(trade, "tradeId") },
            { "info", trade },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "outcome", this.safeString(outcomeObj, "outcome") },
            { "outcomeId", this.safeString(outcomeObj, "outcomeId", outcomeId) },
            { "label", this.safeString(outcomeObj, "label") },
            { "market", this.safeString(outcomeObj, "market") },
            { "order", null },
            { "type", null },
            { "side", "buy" },
            { "takerOrMaker", null },
            { "price", price },
            { "amount", amount },
            { "cost", amount },
            { "fee", null },
        });
    }

    public virtual void handleTrades(WebSocketClient client, object rows)
    {
        //
        //     { "trade": { "tradeId": "0xac6b...", "marketHash": "0x1fec...", "isBettingOutcomeOne": true,
        //                  "totalStake": "1000000", "weightedAverageOdds": "40000000000000000000",
        //                  "betTime": "2026-07-31T18:22:41.000Z", ... } }
        //
        int rowsLength = getArrayLength(rows);
        for (int i = 0; i < rowsLength; i++)
        {
            IDictionary<string, object> row = this.safeDict(getValue(rows, i), "trade", getValue(rows, i));
            IDictionary<string, object> trade = ((IDictionary<string, object>)this.parseSxbetV3PublicTrade(row));
            string? sym = this.safeString(trade, "outcome");
            if ((sym == null))
            {
                continue;
            }
            if ((this.trades == null))
            {
                this.trades = this.createSafeDictionary();
            }
            if (isEqual(this.safeValue(this.trades, sym), null))
            {
                Int64? tradesLimit = this.safeInteger(this.options, "tradesLimit", 1000);
                ((IDictionary<string,object>)this.trades)[(string)sym] = new ArrayCache(tradesLimit);
            }
            ccxt.pro.ArrayCache stored = ((ccxt.pro.ArrayCache)getValue(this.trades, sym));
            stored.append(trade);
            client.resolve(stored, ("trades::" + sym));
        }
    }

